{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 시간의 단축을 인덱스 추가와 조인 정리의 효과로 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "느린 조회를 개선하고 변경에 따른 성능 향상을 확인해야 했다.",
          "action": "인덱스 추가와 조인 정리 전후의 조회 성능을 확인한 근거를 설명한다.",
          "result": "0.4초로 단축된 결과를 두 수정의 효과로 볼 수 있는 근거가 드러난다."
        },
        "expectedEvidence": [
          "조회 시간 단축을 두 수정의 효과로 판단한 근거를 제시한다.",
          "수정 전후 조회 시간을 어떤 조건에서 확인했는지 설명한다.",
          "실행 계획이나 호출 기록의 변화로 성능 향상을 뒷받침한다."
        ]
      },
      "question": "포켓마켓 인턴 때 인덱스 추가와 조인 정리로 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 조회 시간 단축이 두 수정의 효과인지는 무엇으로 확인하셨나요?",
      "answerTip": "당시 직접 확인한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "수정 전후의 조회 조건과 측정 수치를 들어 시간 단축을 두 수정의 효과로 판단한 근거를 설명한다.",
            "실행 계획이나 호출 기록에서 확인한 변화를 성능 향상과 구체적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "수정 전후 시간을 확인했다고 답하지만, 측정 조건이나 변경 효과를 뒷받침하는 설명은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "3.2초에서 0.4초로 줄었다는 결과만 반복하고 수정 효과를 확인한 근거를 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 찾은 스케줄러 동시 실행 원인을 바탕으로 잠금 방식을 선택한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림 스케줄러가 두 서버에서 동시에 실행됐다.",
          "task": "알림 중복 발송 원인에 맞는 수정 방식을 선택해야 했다.",
          "action": "한 서버에서만 실행하는 방법과 구별해 잠금을 선택한 이유를 설명한다.",
          "result": "잠금이 확인된 중복 실행 원인을 막는 방식이라는 판단이 드러난다."
        },
        "expectedEvidence": [
          "한 서버에서만 실행하는 대신 잠금을 택한 이유를 설명한다.",
          "시간순 로그에서 확인한 동시 실행을 잠금의 적용 이유와 연결한다."
        ]
      },
      "question": "포켓마켓 인턴 때 두 서버에서 동시에 돌던 알림 스케줄러를 잠금 키로 고치셨던데요. 한 서버에서만 실행하는 대신 잠금을 택하신 이유는 무엇이었나요?",
      "answerTip": "당시 선택한 이유를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "한 서버에서만 실행하는 방법과 잠금 방식의 차이를 들어 실제 선택 이유를 구체적으로 설명한다.",
            "로그에서 확인한 두 서버의 동시 실행을 잠금이 막는 방식과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "중복 실행을 막기 위해 잠금을 택했다고 답하지만, 다른 방법 대신 선택한 이유는 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금을 적용했다는 사실만 반복하거나 로그로 확인한 원인과 무관한 선택 이유를 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "인터뷰에서 나온 요청을 개발 담당자와 합의할 구현 범위로 좁히는 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 다섯 곳을 인터뷰한 팀 과제에서 개발 담당 팀원과 범위를 조정했다.",
          "task": "수집한 요청 중 이번에 구현할 요구사항의 범위를 정해야 했다.",
          "action": "요청의 목적과 우선순위를 근거로 구현 범위를 정해 개발 담당 팀원과 합의했다.",
          "result": "이번에 포함할 요구사항과 제외할 요구사항의 경계가 명확해졌다."
        },
        "expectedEvidence": [
          "이번에 구현할 요구사항을 고른 근거를 구체적으로 설명한다.",
          "그 근거가 포함하거나 제외한 요구사항에 어떻게 적용됐는지 설명한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 다섯 곳의 인터뷰를 바탕으로 개발 담당 팀원과 범위를 조정하셨던데요. 구현할 요구사항은 무엇을 근거로 고르셨나요?",
      "answerTip": "당시 실제로 내린 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요청의 목적이나 우선순위에 연결해 구현할 요구사항을 고른 근거를 구체적으로 설명한다.",
            "포함하거나 제외한 실제 요구사항을 들어 그 근거가 구현 범위에 적용된 방식을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현할 요구사항을 고른 근거는 제시하지만 중요도나 개발 가능성 같은 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰 내용이나 구현한 기능만 나열하고 구현 범위를 정한 근거는 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서 사용자가 보게 될 화면 내용을 기능 상태에 맞게 구체화한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 상황에서 사용자에게 보여 줄 내용을 구현 가능한 수준으로 정해야 했다.",
          "action": "구체적인 예외 상황의 기능 상태를 근거로 화면에 표시할 내용을 정했다.",
          "result": "예외 발생 시 표시할 상태와 안내가 화면설계서에서 명확해졌다."
        },
        "expectedEvidence": [
          "예외 상황에서 사용자에게 보여 줄 내용을 정한 근거를 설명한다.",
          "실제 예외 사례의 상태나 안내 문구에 그 근거를 적용한 내용을 제시한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요. 예외 상황에서 사용자에게 보여 줄 내용을 무엇을 근거로 정하셨나요?",
      "answerTip": "직접 다뤘던 한 가지 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 예외 상황에서 기능이 어떤 상태인지에 연결해 사용자에게 보여 줄 내용을 정한 근거를 설명한다.",
            "해당 근거가 실제 화면의 상태 표시나 안내 문구에 반영된 내용을 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 내용을 정한 근거는 답하지만 사용자 편의나 명확한 안내 같은 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "작성한 화면이나 도구 사용법만 설명하고 예외 상황의 표시 내용을 정한 근거는 답하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 처방을 통상적인 용량 조정으로 받아들이지 않고 투약 전 확인이 필요하다고 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제가 평소 용량의 두 배로 처방되었다.",
          "task": "해당 처방대로 투약해도 되는지 확인하고 불확실한 상태의 투약을 막아야 했다.",
          "action": "용량 차이의 의미를 판단해 투약을 멈추고 담당의에게 처방을 확인했다.",
          "result": "담당의 확인으로 입력 오류임을 밝혀 잘못된 용량의 투약을 예방했다."
        },
        "expectedEvidence": [
          "통상적인 증량으로 받아들이기 어려웠던 구체적인 근거를 설명한다.",
          "투약을 보류하고 담당의에게 확인해 입력 오류를 확인한 사실을 제시한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배인 진통제 처방을 보고 투약을 멈추셨던데요. 통상적인 용량 조정보다 처방 오류를 의심하신 근거는 무엇이었나요?",
      "answerTip": "당시 판단의 바탕이 된 사실을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "용량 조정으로 받아들이기 어려웠던 근거를 당시 처방 맥락에 연결해 구체적으로 설명한다.",
            "불확실한 처방의 투약을 보류하고 담당의 확인으로 입력 오류를 확인한 사실이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 두 배인 용량이라 확인이 필요했다고 답하지만 당시 판단 근거는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단 근거를 설명하지 못하거나 처방이 의심스러워도 그대로 투약한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "진통제 투여 시각을 다음 근무자의 환자 상태 변화 판단에 필요한 인수인계 정보로 선택한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린 사실을 확인했다.",
          "task": "다음 근무자가 환자 상태를 판단하는 데 필요한 정보를 인수인계에 담아야 했다.",
          "action": "환자 상태 변화 판단에 필요한 정보로 진통제 투여 시각을 인수인계표에 추가했다.",
          "result": "다음 근무자가 투여 시점을 참고해 환자 상태 변화를 이어서 관찰할 수 있다."
        },
        "expectedEvidence": [
          "진통제 투여 시각이 다음 근무자의 상태 판단에 필요한 이유를 설명한다.",
          "투여 시각과 연결해 전달할 환자 상태 변화를 구체적으로 짚는다."
        ]
      },
      "question": "푸른결종합병원에서 인수인계표에 진통제 투여 시각을 추가하셨던데요. 이 정보가 다음 근무자의 환자 상태 판단에 꼭 필요하다고 보신 이유는 무엇이었나요?",
      "answerTip": "당시 상황을 떠올리며 핵심 이유에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투여 시각이 다음 근무자의 상태 판단에 필요한 이유를 수술 후 환자의 구체적인 상태 변화와 연결한다.",
            "투여 시각만 전달하는 것이 아니라 관련된 상태 변화를 함께 인계해야 하는 의미가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "상태 관찰이나 낙상 예방에 필요하다고 답하지만 투여 시각과 환자 상태 변화의 연결은 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "항목을 추가했다는 사실만 반복하거나 다음 근무자의 환자 상태 판단과 무관한 이유를 제시한다."
          ]
        }
      }
    }
  ]
}

{
