  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "축 지름을 불필요하게 키우지 않은 이유를 하중과 베어링 조립 조건에 근거해 설명하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업에서 주어진 하중으로 감속기 축 지름과 베어링을 선정한 과제다.",
          "task": "주어진 하중을 견디고 베어링과 조립할 수 있는 축 지름을 정해야 했다.",
          "action": "하중에 따른 필요 지름과 베어링 조립 조건을 근거로 제출한 치수를 설명한다.",
          "result": "선정한 축 지름이 요구 조건을 충족하면서 불필요하게 크지 않은 이유가 드러난다."
        },
        "expectedEvidence": [
          "축을 더 굵게 하지 않고 제출한 지름으로 정한 이유를 설명한다.",
          "하중이 축에 전달되는 방식과 필요한 지름을 연결한다.",
          "선정한 베어링과 맞물리는 치수를 지름 선정 근거로 설명한다."
        ]
      },
      "question": "기계요소설계 수업에서 주어진 하중으로 감속기 축 지름을 정하셨던데요. 축 지름을 더 굵게 잡는 대신 제출한 치수로 정하신 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 판단했던 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
